package main

import "fmt"

func main() {
    original := []int{1, 2, 3}
    // Make copy and append 4

    // Print original and copy
}

exercises.solution:
package main

import "fmt"

func main() {
    original := []int{1, 2, 3}

    copySlice := make([]int, len(original))
    copy(copySlice, original)

    copySlice = append(copySlice, 4)

    fmt.Println(original)
    fmt.Println(copySlice)
}
